const FONT = "Calibri";
const P = (text, opts = {}) => new Paragraph({ spacing: { after: 120 }, ...opts, children: typeof text === "string" ? [new TextRun({ text, font: FONT, size: 22 })] : text });
const R = (text, o = {}) => new TextRun({ text, font: FONT, size: 22, ...o });
const H1 = t => new Paragraph({ heading: HeadingLevel.HEADING_1, children: [new TextRun(t)], spacing: { before: 360, after: 160 } });
const H2 = t => new Paragraph({ heading: HeadingLevel.HEADING_2, children: [new TextRun(t)], spacing: { before: 280, after: 120 } });
const H3 = t => new Paragraph({ heading: HeadingLevel.HEADING_3, children: [new TextRun(t)], spacing: { before: 200, after: 80 } });
const B = (text, ref = "bullets") => new Paragraph({ numbering: { reference: ref, level: 0 }, spacing: { after: 80 }, children: typeof text === "string" ? [R(text)] : text });
const NUM = text => B(text, "numbers");
const GSRC = JSON.parse(fs.readFileSync("graphemes_src.json", "utf8"));
const NAMES = Object.fromEntries(fs.readFileSync("alphabets.tsv", "utf8").split("\n").slice(1).filter(Boolean).map(l => l.split("\t")).map(p => [p[0], p[1]]));
function ctxOf(m) {
  const c = [];
  if (m.before) c.push(m.before === "V" ? "before a vowel" : m.before === "C" ? "before a consonant" : "before " + [...m.before.replace(/ /g, "")].join("/"));
  if (m.not_before_class === "V" && m.not_before) c.push("not before a vowel or " + [...m.not_before].join("/"));
  else { if (m.not_before_class) c.push("not before a " + (m.not_before_class === "V" ? "vowel" : "consonant")); if (m.not_before) c.push("not before " + [...m.not_before].join("/")); }
  if (m.final) c.push("word-final only"); if (m.not_final) c.push("not word-final"); if (m.initial) c.push("word-initial only");
  return c.length ? " [" + c.join("; ") + "]" : "";
}
// Appendix B: every source consulted — the annotated methods/data list (SOURCES.md) and the orthography descriptions behind Appendix A.
function sourcesAppendix() {
  const out = [];
  const md = fs.readFileSync("SOURCES.md", "utf8").split("\n");
  out.push(H2("B.1 Data, methods and software (annotated; from SOURCES.md)"));
  let para = [];
  const flush = () => { if (!para.length) return; const t = para.join(" ").trim(); para = [];
    const m = t.match(/^\*\*(.+?)\*\*\s*(.*)$/); if (m) out.push(P([R(m[1] + " ", { bold: true }), R(m[2].replace(/\*([^*]+)\*/g, "$1").replace(/`([^`]+)`/g, "$1"))]));
    else if (t) out.push(P(t.replace(/\*([^*]+)\*/g, "$1").replace(/`([^`]+)`/g, "$1"))); };
  for (const line of md) {
    if (line.startsWith("# ")) continue;
    if (line.startsWith("## ")) { flush(); out.push(H3(line.slice(3))); continue; }
    if (!line.trim()) { flush(); continue; }
    para.push(line.replace(/^[-*]\s+/, ""));
  }
  flush();
  out.push(H2("B.2 Orthography descriptions used for the grapheme inventories"));
  out.push(P("Every description consulted for Appendix A, alphabetically by title, with the languages it was used for. URLs were live on 14 October 2026."));
  const by = new Map();
  for (const [code, g] of Object.entries(GSRC)) for (const src of g.sources || []) { const key = (src.url || src.title || "").trim(); if (!key) continue;
    if (!by.has(key)) by.set(key, { title: src.title || src.url, url: src.url || "", langs: [] }); by.get(key).langs.push(NAMES[code] || code); }
  const list = [...by.values()].sort((a, b) => a.title.localeCompare(b.title));
  for (const e of list) out.push(new Paragraph({ spacing: { after: 80 }, indent: { left: 720, hanging: 720 }, children: [R(e.title + (e.url ? " — " + e.url : "") + " [" + [...new Set(e.langs)].join(", ") + "]")] }));
  return out;
}
function graphemeAppendix() {
  const out = [];
  for (const code of Object.keys(GSRC).sort((a, b) => (NAMES[a] || a).localeCompare(NAMES[b] || b))) {
    const g = GSRC[code], name = NAMES[code] || code;
    out.push(H3(name));
    const mg = g.multigraphs || [], C = mg.filter(m => m.cls === "C"), V = mg.filter(m => m.cls === "V");
    const hasIpa = s => /\/[^/]+\/|\[[^\]]+\]|∅/.test(s);
    const sounds = m => {   // same rule as the app: a note that lists the values one by one replaces "all phonemes, then note"
      const phons = (m.phon || "").split(/\s+/).filter(Boolean), clauses = (m.note || "").split(/;\s*/).map(s => s.trim()).filter(Boolean);
      if (phons.length > 1 && clauses.filter(hasIpa).length >= Math.min(2, phons.length)) {
        const core = p => p.replace(/^[(/[]+|[,)/\]]+$/g, "");
        const missing = phons.filter(p => hasIpa(p) && !clauses.some(c => c.includes(p) || c.includes("/" + core(p) + "/") || c.includes("[" + core(p) + "]")));
        return " " + clauses.map(c => hasIpa(c) ? c : (missing.length ? missing.shift() + " " : "") + c).concat(missing).join(" · ");
      }
      return (m.phon ? " " + m.phon : "") + (m.note ? " (" + m.note + ")" : "");
    };
    const item = m => m.g + sounds(m) + ctxOf(m);
    if (g.status === "exclude") out.push(P("Graphemic CV not offered. " + (g.notes || "")));
    else if (!mg.length) out.push(P("No multi-letter graphemes. Doubled letters: " + (g.doubles || "n/a") + "." + (g.confidence ? " Confidence: " + g.confidence + "." : "")));
    else {
      out.push(P([R(mg.length + " multi-letter graphemes. Doubled letters: " + (g.doubles || "n/a") + "." + (g.confidence ? " Confidence: " + g.confidence + "." : ""))]));
      if (C.length) out.push(P([R("C: ", { bold: true }), R(C.map(item).join("; "))]));
      if (V.length) out.push(P([R("V: ", { bold: true }), R(V.map(item).join("; "))]));
    }
    if (g.ambiguities) out.push(P([R("Known ambiguities: ", { bold: true }), R(g.ambiguities)]));
    if (g.notes && g.status !== "exclude") out.push(P([R("Notes: ", { bold: true }), R(g.notes)]));
    if ((g.sources || []).length) out.push(P([R("Sources: ", { bold: true }), R(g.sources.map(x => (x.title || "") + (x.url ? " — " + x.url : "")).join("; "))], { spacing: { after: 200 } }));
  }
  return out;
}
const Code = t => new TextRun({ text: t, font: "Consolas", size: 20 });

function table(headers, data, widths, fontSize = 18) {
  const total = widths.reduce((a, b) => a + b, 0);
  const cell = (t, w, head = false) => new TableCell({
    width: { size: w, type: WidthType.DXA },
    shading: head ? { type: ShadingType.CLEAR, fill: "E7E6E6", color: "auto" } : undefined,
    margins: { top: 40, bottom: 40, left: 80, right: 80 },
    children: [new Paragraph({ spacing: { after: 0 }, children: [new TextRun({ text: String(t ?? ""), font: FONT, size: fontSize, bold: head })] })],
  });
  return new Table({
    width: { size: total, type: WidthType.DXA }, columnWidths: widths,
    rows: [new TableRow({ tableHeader: true, children: headers.map((h, i) => cell(h, widths[i], true)) }),
      ...data.map(r => new TableRow({ cantSplit: true, children: r.map((v, i) => cell(v, widths[i])) }))],
  });
}

