const langTable = table(
  ["Language", "Family", "Script / CV type", "Sources", "Ref. words", "Bands", "Bank", "Rules and notes"],
  rows.map(r => [r.name, r.family, r.kind, r.src, fmt(r.ref), r.bands, fmt(r.bank), r.rules]),
  [1500, 1250, 1350, 2700, 850, 850, 800, 4140], 15);

